// Unit pins for lib/agent-identity.ts, the token and challenge primitives the
// optional-identity chain is built on. The chain itself (auth.md to PRM to AS
// metadata to the identity endpoint, and where the 401 may appear) is walked
// in auth-chain.test.ts; this file covers the edges that walk never reaches.

import { afterEach, describe, expect, it } from "vitest";
import {
	ASSERTION_TTL_SECONDS,
	bearerFromHeader,
	challengeDescription,
	IDENTITY_ENDPOINT,
	ISSUER,
	JWT_TYP,
	mintIdentityAssertion,
	PRM_URL,
	resetSigningKeyForTests,
	SCOPES,
	verifyIdentityAssertion,
	wwwAuthenticate,
} from "@/lib/agent-identity";
import { SITE } from "@/lib/constants";

function b64(v: unknown): string {
	return Buffer.from(JSON.stringify(v)).toString("base64url");
}

describe("constants agree with the site", () => {
	it("issuer, PRM and identity endpoint are all on this origin", () => {
		expect(ISSUER).toBe(SITE.domain);
		expect(PRM_URL).toBe(`${SITE.domain}/.well-known/oauth-protected-resource`);
		expect(IDENTITY_ENDPOINT).toBe(`${SITE.domain}/agent/identity`);
		expect(SCOPES).toEqual(["docs.read"]);
		expect(ASSERTION_TTL_SECONDS).toBe(30 * 24 * 60 * 60);
	});
});

describe("mint and verify", () => {
	it("a fresh assertion verifies and carries the anonymous claims", async () => {
		const { token, claims } = await mintIdentityAssertion();
		expect(token.split(".")).toHaveLength(3);
		const header = JSON.parse(Buffer.from(token.split(".")[0], "base64url").toString());
		expect(header).toEqual({ alg: "HS256", typ: JWT_TYP });
		expect(claims.iss).toBe(ISSUER);
		expect(claims.aud).toBe(ISSUER);
		expect(claims.sub).toMatch(/^reg_[A-Za-z0-9_-]{22}$/);
		expect(claims.exp - claims.iat).toBe(ASSERTION_TTL_SECONDS);
		expect(claims.scope).toBe("docs.read");
		expect(claims.registration_type).toBe("anonymous");
		const verdict = await verifyIdentityAssertion(token);
		expect(verdict).toEqual({ ok: true, claims });
	});

	it("re-issuing for a sub keeps the sub and mints a new expiry", async () => {
		const first = await mintIdentityAssertion({ now: 1_700_000_000_000 });
		const again = await mintIdentityAssertion({ sub: first.claims.sub });
		expect(again.claims.sub).toBe(first.claims.sub);
		expect(again.claims.exp).toBeGreaterThan(first.claims.exp);
	});

	it("two anonymous registrations never share a registration id", async () => {
		const a = await mintIdentityAssertion();
		const b = await mintIdentityAssertion();
		expect(a.claims.sub).not.toBe(b.claims.sub);
	});

	it("expiry is judged against the clock it is given", async () => {
		const { token } = await mintIdentityAssertion({ now: 1_000_000, ttlSeconds: 60 });
		expect((await verifyIdentityAssertion(token, 1_000_000 + 59_000)).ok).toBe(true);
		const late = await verifyIdentityAssertion(token, 1_000_000 + 61_000);
		expect(late).toEqual({ ok: false, reason: "expired" });
	});

	it.each([
		["not a jwt at all", "garbage"],
		["two segments", "a.b"],
		["four segments", "a.b.c.d"],
		["non-base64url bytes", "a+b.c/d.e=f"],
		["header is not JSON", `${Buffer.from("nope").toString("base64url")}.${b64({})}.AAAA`],
		["wrong alg", `${b64({ alg: "none", typ: JWT_TYP })}.${b64({ sub: "x", exp: 1, iat: 1 })}.AAAA`],
		["wrong typ", `${b64({ alg: "HS256", typ: "JWT" })}.${b64({ sub: "x", exp: 1, iat: 1 })}.AAAA`],
		["missing sub", `${b64({ alg: "HS256", typ: JWT_TYP })}.${b64({ exp: 1, iat: 1 })}.AAAA`],
	])("%s is malformed", async (_name, token) => {
		expect(await verifyIdentityAssertion(token)).toEqual({ ok: false, reason: "malformed" });
	});

	it("a well-formed token from another issuer is wrong_issuer, not malformed", async () => {
		const token = `${b64({ alg: "HS256", typ: JWT_TYP })}.${b64({
			iss: "https://example.com",
			aud: ISSUER,
			sub: "reg_x",
			iat: 1,
			exp: 4_000_000_000,
		})}.AAAA`;
		expect(await verifyIdentityAssertion(token)).toEqual({ ok: false, reason: "wrong_issuer" });
	});

	it("a tampered payload fails the signature, even with our issuer", async () => {
		const { token } = await mintIdentityAssertion();
		const [h, p, s] = token.split(".");
		const claims = JSON.parse(Buffer.from(p, "base64url").toString());
		const forged = `${h}.${b64({ ...claims, scope: "docs.write" })}.${s}`;
		expect(await verifyIdentityAssertion(forged)).toEqual({
			ok: false,
			reason: "invalid_signature",
		});
	});
});

describe("the signing key", () => {
	afterEach(() => {
		delete process.env.AGENT_IDENTITY_SECRET;
		resetSigningKeyForTests();
	});

	it("AGENT_IDENTITY_SECRET changes the key, so old assertions stop verifying", async () => {
		const { token } = await mintIdentityAssertion();
		process.env.AGENT_IDENTITY_SECRET = "a different key for this test";
		resetSigningKeyForTests();
		expect((await verifyIdentityAssertion(token)).ok).toBe(false);
		const fresh = await mintIdentityAssertion();
		expect((await verifyIdentityAssertion(fresh.token)).ok).toBe(true);
	});
});

describe("bearerFromHeader", () => {
	it("returns null when there is no Authorization header or another scheme", () => {
		expect(bearerFromHeader(null)).toBeNull();
		expect(bearerFromHeader("")).toBeNull();
		expect(bearerFromHeader("Basic dXNlcjpwYXNz")).toBeNull();
		expect(bearerFromHeader('Signature keyId="x"')).toBeNull();
		expect(bearerFromHeader("Bearerx")).toBeNull();
	});

	it("extracts the token, case-insensitively on the scheme, trimmed", () => {
		expect(bearerFromHeader("Bearer abc")).toBe("abc");
		expect(bearerFromHeader("bearer abc")).toBe("abc");
		expect(bearerFromHeader("  BEARER   abc  ")).toBe("abc");
	});

	it("a bare Bearer with nothing after it is a presented, empty token", () => {
		// It must NOT read as "no credential": the client meant to send one.
		expect(bearerFromHeader("Bearer")).toBe("");
		expect(bearerFromHeader("Bearer   ")).toBe("");
	});
});

describe("the challenge header", () => {
	it("without a reason: realm and resource_metadata, no error code (RFC 6750 3.1)", () => {
		const h = wwwAuthenticate();
		expect(h).toMatch(/^Bearer realm="/);
		expect(h).toContain(`resource_metadata="${PRM_URL}"`);
		expect(h).not.toContain("error=");
	});

	it("with a reason: error=invalid_token and a description that names the reason", () => {
		for (const reason of ["malformed", "invalid_signature", "expired", "wrong_issuer"] as const) {
			const h = wwwAuthenticate(reason);
			expect(h).toContain('error="invalid_token"');
			expect(h).toContain(`error_description="${challengeDescription(reason)}"`);
			expect(h).toContain(`resource_metadata="${PRM_URL}"`);
			// Descriptions are quoted-string safe: no embedded double quotes.
			expect(challengeDescription(reason)).not.toContain('"');
		}
	});
});
